import re

parsed_rows = []
habit_order = None

for note in notes_data:
    # Extract date from title: "Habit Tracking Log for 2023-05-17"
    m = re.search(r'(\d{4}-\d{2}-\d{2})', note["title"])
    if not m:
        continue
    date_str = m.group(1)

    # Parse content lines: "habit: yes/no"
    habits = {}
    for line in note["content"].splitlines():
        line = line.strip()
        if ":" in line:
            key, val = line.split(":", 1)
            key = key.strip()
            val = val.strip().lower()
            if val in ("yes", "no"):
                habits[key] = val

    if habit_order is None:
        # Preserve order from first note's content lines
        habit_order = []
        for line in note["content"].splitlines():
            line = line.strip()
            if ":" in line:
                key = line.split(":", 1)[0].strip()
                if key in habits:
                    habit_order.append(key)

    parsed_rows.append((date_str, habits))

print(f"Parsed {len(parsed_rows)} rows")
print("Habit order:", habit_order)
print("First row:", parsed_rows[0])

